import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/moran_local_2021_energy.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

# Load data
energy_df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

# Create neighbors dictionary
neighbors_dict = {}
for _, row in adj_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighbors_dict:
        neighbors_dict[borough] = []
    neighbors_dict[borough].append(neighbor)

# Create energy dictionary
energy_dict = dict(zip(energy_df['borough'], energy_df['Energy_value']))

# Compute average neighbor energy for each borough
average_neighbor_energy = {}
for borough in energy_df['borough']:
    neighbors = neighbors_dict.get(borough, [])
    if not neighbors:
        avg = np.nan
    else:
        neighbor_values = [energy_dict.get(neighbor, np.nan) for neighbor in neighbors]
        neighbor_values = [v for v in neighbor_values if not np.isnan(v)]
        if not neighbor_values:
            avg = np.nan
        else:
            avg = np.mean(neighbor_values)
    average_neighbor_energy[borough] = avg

# Compute mean energy
mean_energy = energy_df['Energy_value'].mean()

# Compute observed local indicators
observed_local_indicators = {}
for borough in energy_df['borough']:
    energy_value = energy_dict[borough]
    avg_neighbor = average_neighbor_energy[borough]
    indicator = (energy_value - mean_energy) * (avg_neighbor - mean_energy)
    observed_local_indicators[borough] = indicator

# Perform permutation test
n_permutations = 500
permuted_indicators = {borough: [] for borough in energy_df['borough']}

for _ in range(n_permutations):
    # Shuffle energy values
    shuffled_energy = energy_df['Energy_value'].sample(frac=1).reset_index(drop=True)
    shuffled_energy_dict = dict(zip(energy_df['borough'], shuffled_energy))

    # Compute average neighbor energy for each borough in this permutation
    permuted_avg_neighbor = {}
    for borough in energy_df['borough']:
        neighbors = neighbors_dict.get(borough, [])
        if not neighbors:
            avg = np.nan
        else:
            neighbor_values = [shuffled_energy_dict.get(neighbor, np.nan) for neighbor in neighbors]
            neighbor_values = [v for v in neighbor_values if not np.isnan(v)]
            if not neighbor_values:
                avg = np.nan
            else:
                avg = np.mean(neighbor_values)
        permuted_avg_neighbor[borough] = avg

    # Compute local indicators for this permutation
    for borough in energy_df['borough']:
        energy_value = shuffled_energy_dict[borough]
        avg_neighbor = permuted_avg_neighbor[borough]
        indicator = (energy_value - mean_energy) * (avg_neighbor - mean_energy)
        permuted_indicators[borough].append(indicator)

# Compute p-values for each borough
hot_spots = []
cold_spots = []

for borough in energy_df['borough']:
    observed = observed_local_indicators[borough]
    permuted = np.array(permuted_indicators[borough])
    energy_value = energy_dict[borough]

    if observed > 0:
        hot_count = np.sum(permuted >= observed)
        hot_p = hot_count / n_permutations
        if hot_p < 0.05:
            if energy_value > mean_energy:
                hot_spots.append((borough, observed))
            else:
                cold_spots.append((borough, observed))
    elif observed < 0:
        cold_count = np.sum(permuted <= observed)
        cold_p = cold_count / n_permutations
        if cold_p < 0.05:
            if energy_value < mean_energy:
                cold_spots.append((borough, observed))
            else:
                hot_spots.append((borough, observed))

# Prepare final answer
results = []
for borough, value in hot_spots:
    results.append(f"{borough} (HH, statistical method={value})")
for borough, value in cold_spots:
    results.append(f"{borough} (LL, statistical method={value})")

print("FINAL ANSWER: " + ", ".join(results))
